#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=5

# The prompts need a person at a terminal; without one they would all skip straight through.
if [[ ! -t 0 ]]; then
  printf 'This wizard is interactive: run it in a terminal, not through a tool that has no stdin.\n' >&2
  exit 1
fi

banner "Kiln: GitHub App for worker tokens"

# Where Kiln reads its config (see src/paths.ts).
case "$(uname -s)" in
  Darwin) DEFAULT_CONFIG="$HOME/Library/Application Support/kiln/config" ;;
  *)      DEFAULT_CONFIG="${XDG_CONFIG_HOME:-$HOME/.config}/kiln" ;;
esac
KILN_CONFIG="${KILN_CONFIG_DIR:-$DEFAULT_CONFIG}"
KEY_DEST="$KILN_CONFIG/github-app.pem"

# ── 1. Create the App ─────────────────────────────────────────────────────
stage "Create the GitHub App"
say "A GitHub App lets Kiln mint a short-lived token for one repository at a time."
say "Nothing here uses your own token."
open_url "https://github.com/settings/apps/new"
step "GitHub App name: anything unique, e.g. kiln-workers-<your-handle>."
step "Homepage URL: https://github.com/talvor/kiln (it is not used)."
step "Webhook: untick 'Active'. Kiln needs no webhook."
step "Repository permissions, each set to Read-only:"
say "      Actions, Contents, Issues, Pull requests  (Metadata is added for you)"
step "Leave every other permission as 'No access'."
step "Where can this GitHub App be installed?  Only on this account."
step "Click 'Create GitHub App'."
pause "Press Enter once the App is created and you can see its settings page."

# ── 2. App id and slug ────────────────────────────────────────────────────
stage "Note the App id and name"
say "On the App's settings page (General → About):"
step "Copy the 'App ID' (a number, not the Client ID)."
ask APP_ID "App ID:"
if [[ ! "$APP_ID" =~ ^[0-9]+$ ]]; then
  warn "That is not a number. Re-run and paste the 'App ID' (not the Client ID)."
  exit 1
fi
step "Look at the page URL: github.com/settings/apps/<this-part>"
ask APP_SLUG "App's URL name:"
[[ -n "$APP_SLUG" ]] || { warn "The URL name is needed for the next step."; exit 1; }

# ── 3. Private key ────────────────────────────────────────────────────────
stage "Generate the private key"
say "Kiln signs a short JWT with this key to prove it is the App."
step "Scroll to 'Private keys' and click 'Generate a private key'."
step "Your browser downloads a .pem file."
pause "Press Enter once the download has finished."
LATEST=$(ls -t "$HOME"/Downloads/*.private-key.pem 2>/dev/null | head -n1 || true)
if [[ -n "$LATEST" ]]; then
  note "Found: $LATEST"
  ask DOWNLOADED_KEY "Path to the .pem [Enter for the one above]:"
  DOWNLOADED_KEY="${DOWNLOADED_KEY:-$LATEST}"
else
  ask DOWNLOADED_KEY "Path to the downloaded .pem:"
fi
DOWNLOADED_KEY="${DOWNLOADED_KEY/#\~/$HOME}"
if [[ ! -f "$DOWNLOADED_KEY" ]] || ! grep -q "BEGIN .*PRIVATE KEY" "$DOWNLOADED_KEY"; then
  warn "That is not a PEM private key file: $DOWNLOADED_KEY"
  exit 1
fi
mkdir -p "$KILN_CONFIG"
if [[ -e "$KEY_DEST" ]] && ! confirm "Replace the existing $KEY_DEST?"; then
  warn "Left the existing key alone."
else
  install -m 600 "$DOWNLOADED_KEY" "$KEY_DEST"
  printf '  %s✓ saved%s the key to %s (owner-only)\n' "$GREEN" "$RESET" "$KEY_DEST"
fi
note "The copy in Downloads is no longer needed; delete it when you are done."

# ── 4. Install on repositories ────────────────────────────────────────────
stage "Install the App on your repositories"
say "The App can only mint tokens for repositories it is installed on."
open_url "https://github.com/apps/${APP_SLUG}/installations/new"
step "Choose your account."
step "Select 'Only select repositories' and tick the repositories Kiln works on"
say "      (e.g. talvor/kiln and talvor/kiln-fixture)."
step "Click 'Install'."
pause "Press Enter once it is installed."

# ── 5. Write github.json and check it ─────────────────────────────────────
stage "Write github.json and check it"
CONFIG_FILE="$KILN_CONFIG/github.json"
if [[ -e "$CONFIG_FILE" ]] && ! confirm "Replace the existing $CONFIG_FILE?"; then
  warn "Left the existing github.json alone."
else
  printf '{\n  "app": { "id": %s, "privateKeyFile": "%s" }\n}\n' "$APP_ID" "$KEY_DEST" > "$CONFIG_FILE"
  chmod 600 "$CONFIG_FILE"
  printf '  %s✓ wrote%s %s\n' "$GREEN" "$RESET" "$CONFIG_FILE"
  note "Permissions default to read-only (see docs/router.md to change them)."
fi

CHECK_REPO=""
until [[ "$CHECK_REPO" =~ ^[^/[:space:]]+/[^/[:space:]]+$ ]]; do
  ask CHECK_REPO "A repository to test, as owner/repo (e.g. talvor/kiln-fixture):"
  [[ "$CHECK_REPO" =~ ^[^/[:space:]]+/[^/[:space:]]+$ ]] || warn "Use the form owner/repo."
done
if [[ -f src/ghtoken.ts ]] && command -v deno >/dev/null 2>&1; then
  say "Asking GitHub for a token limited to ${CHECK_REPO}..."
  if CHECK_REPO="$CHECK_REPO" KILN_CONFIG="$KILN_CONFIG" deno eval --ext ts '
    import { createTokenMinter } from "./src/ghtoken.ts";
    const minter = createTokenMinter({
      configDir: Deno.env.get("KILN_CONFIG")!,
      warn: (m, f) => console.error("  " + m, JSON.stringify(f ?? {})),
    });
    const token = await minter.tokenFor(Deno.env.get("CHECK_REPO")!);
    if (!token) Deno.exit(1);
    console.log("  got a token starting " + token.slice(0, 4) + "…");
  '; then
    printf '  %s✓ works%s: workers on %s will get a scoped token\n' "$GREEN" "$RESET" "$CHECK_REPO"
  else
    SKIPPED+=("Token check for $CHECK_REPO failed: is the App installed on it, and is the App ID right?")
    warn "Could not get a token (see the message above)."
  fi
else
  SKIPPED+=("Check it works: run this from a Kiln checkout that has src/ghtoken.ts")
  warn "Skipped the check: needs a Kiln checkout with src/ghtoken.ts, and deno."
fi

note "Restart is not needed: Kiln reads github.json at each launch."
finish
